import {MISSIONS,LEVELS,MAX_SCORE} from './missions.js';
import {freshState,suggestions,score,rank,validateState,report} from './engine.js';
const STORAGE='odysseus-voyage-v1';
const app=document.querySelector('#app'),dialog=document.querySelector('#info-dialog'),dialogContent=document.querySelector('#dialog-content');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('de-CH',{maximumFractionDigits:1}).format(n);
let state=null,view='welcome',storageOK=true,timerRunning=true,lastTick=Date.now(),toastTimeout;
try{const raw=localStorage.getItem(STORAGE);if(raw){const parsed=JSON.parse(raw);if(validateState(parsed))state=parsed;else storageOK=false;}}catch{storageOK=false;}
const icon=(name)=>({arrow:'→',sound:'♫',mute:'♪',help:'?',book:'▤',check:'✓',anchor:'⚓',download:'↓'}[name]??name);
function announce(s){document.querySelector('#announcement').textContent=s;}
function save(){if(!state)return;try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{if(storageOK){storageOK=false;toast('Speichern ist hier nicht möglich. Lade am Ende deinen Bericht herunter.');}}}
function toast(s){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=s;document.body.append(e);clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>e.remove(),4200);}
function sound(success=false){if(!state?.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const base=success?392:261.63;[0,1,2].forEach((n)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=base*[1,1.25,1.5][n];g.gain.setValueAtTime(0,ctx.currentTime+n*.1);g.gain.linearRampToValueAtTime(.065,ctx.currentTime+n*.1+.015);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+n*.1+.35);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+n*.1);o.stop(ctx.currentTime+n*.1+.4);});setTimeout(()=>ctx.close(),900);}catch{}}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='confetti';box.setAttribute('aria-hidden','true');for(let i=0;i<40;i++){const e=document.createElement('i');e.style.left=`${Math.random()*100}%`;e.style.animationDelay=`${Math.random()*.6}s`;e.style.background=['#e7b764','#9bd3c8','#f7f1e5'][i%3];box.append(e);}document.body.append(box);setTimeout(()=>box.remove(),3300);}
function openDialog(title,body){dialogContent.innerHTML=`<h2 id="dialog-title">${escape(title)}</h2>${body}`;dialog.showModal();}
document.querySelector('#dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function header(){return `<header class="topbar"><button class="brand" data-action="home" aria-label="Zur Startseite"><img src="./assets/favicon.svg" alt=""><span><strong>ODYSSEUS</strong><small>Rückfahrt mit Hindernissen</small></span></button><nav class="toolbar" aria-label="Spielmenü">${view!=='welcome'?`<button class="ghost" data-action="sound" aria-label="Ton ${state?.sound?'ausschalten':'einschalten'}" aria-pressed="${!!state?.sound}"><span aria-hidden="true">${icon(state?.sound?'sound':'mute')}</span><span class="label-desktop">Ton ${state?.sound?'an':'aus'}</span></button><button class="ghost" data-action="logbook"><span aria-hidden="true">${icon('book')}</span><span class="label-desktop">Logbuch</span></button>`:''}<button class="ghost" data-action="help"><span aria-hidden="true">${icon('help')}</span><span class="label-desktop">So spielt ihr</span></button></nav></header>${!storageOK?'<div class="storage-warning" role="status">Lokales Speichern ist nicht verfügbar oder der alte Spielstand ist unlesbar. Das Spiel funktioniert trotzdem; sichere dein Ergebnis als Bericht.</div>':''}`;}
function footer(){return `<footer class="site-footer"><span>Nach Auguste Lechner · 12 Missionen · Gemeinsam klüger heimkommen</span><div class="footer-links"><button class="text-button" data-action="sources">Text & Bilder</button><button class="text-button" data-action="privacy">Speichern & Datenschutz</button></div></footer>`;}
function welcome(){return `${header()}<main id="main" class="page-enter"><section class="hero"><img class="hero-image" src="./assets/fleet-storm.webp" alt="Ein antikes Schiff kämpft sich durch stürmische Wellen. Freie Illustration."><div class="hero-inner"><p class="eyebrow">Literaturspiel nach Auguste Lechner</p><h1>Zwölf Missionen.<br>Ein Ziel.<br><em>Endlich Ithaka.</em></h1><p class="hero-copy">Götter im Weg. Wind im Gepäck. Und ein Kapitän, der manchmal besser geschwiegen hätte. Bringt eure Crew nach Hause.</p><div class="facts"><span><b>4 Level</b>mit steigendem Seegang</span><span><b>60 Punkte</b>für kluge Köpfe</span><span><b>45–60 Min.</b>mit Besprechung</span></div>${state?`<div class="resume"><p><strong>${escape(state.name)}</strong><br>${state.phase==='result'?'Ithaka erreicht':`Mission ${state.index+1} von 12`} · ${fmt(score(state))} Punkte gespeichert</p><button class="button" data-action="resume">${state.phase==='result'?'Ergebnis öffnen':'Weitersegeln'} →</button><button class="text-button" data-action="new">Neu anfangen</button></div>`:`<form id="start-form" class="start-box"><label class="crew-label" for="crew-name">Wie heisst euer Schiff?</label><div class="start-row"><input class="name-input" id="crew-name" name="name" placeholder="z. B. Die wilden Widder" maxlength="40" autocomplete="off"><button class="button" type="submit">Leinen los <span aria-hidden="true">→</span></button></div><div class="mode-row"><label><input type="radio" name="mode" value="crew" checked> Als Crew (2–4)</label><label><input type="radio" name="mode" value="solo"> Allein auf See</label></div></form>`}</div></section><section class="overview" aria-labelledby="overview-title"><div class="section-heading"><h2 id="overview-title">Der Heimweg hat vier Schwierigkeitsgrade</h2><p>Selber antworten. Listen sortieren. Fehler entlarven. Urteile begründen.</p></div><div class="level-grid">${LEVELS.map((l,i)=>`<article class="level-card"><span class="number">0${i+1}</span><h3>${l.name}</h3><p>${l.subtitle}</p><p class="small">3 Missionen · ${[9,12,15,24][i]} Punkte</p></article>`).join('')}</div></section></main>${footer()}`;}
function route(){return `<aside class="route" aria-label="Reiseroute"><p class="route-heading">Eure Heimreise</p>${LEVELS.map((l,i)=>`<div class="route-group ${Math.floor(state.index/3)===i?'active':''}"><p class="eyebrow">Level ${i+1}</p><h3>${l.name}</h3><div class="route-dots">${[0,1,2].map(j=>{let n=i*3+j;return `<span class="route-dot ${state.answers[n].confirmed?'done':''} ${state.index===n?'current':''}" ${state.index===n?'aria-current="step"':''} aria-label="Mission ${n+1}: ${state.answers[n].confirmed?'abgeschlossen':state.index===n?'aktuell':'noch offen'}">${state.answers[n].confirmed?'✓':n+1}</span>`;}).join('')}</div></div>`).join('')}<p class="route-end">Ithaka wartet.</p></aside>`;}
function timeLabel(){const seconds=Math.floor(state?.answers[state.index]?.elapsed??0);return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function gameStatus(){const done=state.answers.filter(a=>a.confirmed).length;return `<div class="game-header"><div class="game-status"><div class="crew-identity"><p class="eyebrow">${state.mode==='solo'?'Allein auf See':'Eure Crew'}</p><p class="crew-name">${escape(state.name)}</p></div><div class="voyage-progress"><div class="progress-label"><span>${done} von 12 Missionen geschafft</span><span>${done===12?'Ithaka erreicht':'Kurs: Ithaka'}</span></div><div class="progress" role="progressbar" aria-label="Abgeschlossene Missionen" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${done}"><div class="progress-fill" style="width:${done/12*100}%"></div></div></div><p class="points">${fmt(score(state))} <small>/ 60</small></p></div></div>`;}
function inputField(f,i,type,answer){const value=answer.fields[f.id]??'',isShort=!!f.accept||['animal','god','plant','alias','owner','instigator','lightning'].includes(f.id);return `<label class="answer-field" for="answer-${f.id}"><span class="field-label"><span class="field-number">${String(i+1).padStart(2,'0')}</span>${escape(f.label)}</span>${isShort?`<input id="answer-${f.id}" name="${f.id}" value="${escape(value)}" placeholder="${escape(f.placeholder)}" maxlength="120" autocomplete="off" required>`:`<textarea id="answer-${f.id}" name="${f.id}" placeholder="${escape(f.placeholder)}" maxlength="3000" rows="${type==='argument'?3:2}" required>${escape(value)}</textarea>`}</label>`;}
function orderList(answer){return `<p class="order-instruction">Mit den Pfeilen verschieben; am Computer auch ziehen. Ganz oben steht die früheste Station.</p><ol class="order-list" id="order-list">${answer.order.map((name,i)=>`<li class="order-item" draggable="true" data-order-index="${i}"><span class="order-index">${i+1}</span><span class="order-title">${escape(name)}</span><span class="order-controls"><button type="button" data-action="move" data-index="${i}" data-direction="-1" aria-label="${name} nach oben" ${i===0?'disabled':''}>↑</button><button type="button" data-action="move" data-index="${i}" data-direction="1" aria-label="${name} nach unten" ${i===answer.order.length-1?'disabled':''}>↓</button></span></li>`).join('')}</ol>`;}
function answerScreen(m,a){return `<p class="prompt">${escape(m.prompt)}</p>${m.type==='argument'?'<p class="source-note">Hier zählt die Begründung: Nach dem Abgeben vergleicht ihr eure Antwort mit einem Bewertungsraster. Unterschiedliche Urteile sind möglich.</p>':''}<form id="mission-form" novalidate>${m.type==='order'?orderList(a):''}<div class="mission-form ${m.type==='argument'?'argument':''}">${(m.fields??m.events).map((f,i)=>inputField(f,i,m.type,a)).join('')}</div>${a.hint?`<aside class="hint-box"><strong>Eure Rettungsleine</strong>${escape(m.hint)}</aside>`:''}<div id="form-feedback"></div><div class="action-bar"><button type="button" class="hint-button" data-action="hint" ${state.hintUsed&&!a.hint?'disabled':''}>${icon('anchor')} ${a.hint?'Hinweis ist geöffnet':state.hintUsed?'Rettungsleine verbraucht':'Rettungsleine (1×)'}</button><div class="action-right"><span class="save-note">${storageOK?'Auf diesem Gerät gespeichert':'Ohne lokale Speicherung'}</span><button type="submit" class="button dark">Antworten abgeben →</button></div></div></form>`;}
function autoCriterion(m,c,i){return (m.type==='order'&&i===0)||Array.isArray(c.accept)&&c.accept.every(x=>typeof x==='string');}
function readBack(m,a){return `<details class="read-back"><summary>Eure eingereichten Antworten</summary><dl>${m.type==='order'?`<dt>Reihenfolge</dt><dd>${a.order.map(escape).join(' → ')}</dd>`:''}${(m.fields??m.events).map(f=>`<dt>${escape(f.label)}</dt><dd>${escape(a.fields[f.id])}</dd>`).join('')}</dl></details>`;}
function reviewScreen(m,a){const checks=a.reviewed??m.criteria.map(()=>false),done=checks.filter(Boolean).length,suggest=suggestions(m,a);return `<div class="review-intro"><h3>${m.type==='argument'?'Der Kapitänsrat prüft eure Belege':'Zeit für den Faktencheck'}</h3><p>${m.type==='argument'?'Vergleicht eure Begründungen mit dem Raster. Wählt für jedes Kriterium die erreichten Punkte. Ihr dürft anders urteilen als die Musterlösung – die Fakten und Belege müssen stimmen.':'Eindeutige Namen und die Reihenfolge werden automatisch verglichen. Längere Antworten bewertet ihr anhand der Musterlösung selbst. Der Wortvergleich ist dabei nur eine Orientierung.'}</p><p class="review-score" id="review-total">${fmt(a.scores.reduce((s,v)=>s+v,0))} / ${fmt(m.criteria.reduce((s,c)=>s+c.points,0))} Punkte</p></div><div class="review-list">${m.criteria.map((c,i)=>{const auto=autoCriterion(m,c,i),answer=c.field?a.fields[c.field]:a.order.join(' → ');let choices=c.points===.5?[0,.5]:Array.from({length:c.points+1},(_,i)=>i);return `<fieldset class="criterion"><legend>${i+1}. ${escape(c.label)} · ${fmt(c.points)} ${c.points===1?'Punkt':'Punkte'}</legend><p class="your-answer"><strong>Eure Antwort</strong>${escape(answer)}</p><p class="model-answer"><strong>${m.type==='argument'?'Bewertungskriterium':'Musterlösung'}</strong>${escape(c.explanation)}</p><div class="criterion-scores">${choices.map(v=>`<label class="score-choice"><input type="radio" name="criterion-${i}" value="${v}" data-score-index="${i}" ${checks[i]&&a.scores[i]===v?'checked':''}>${fmt(v)} ${v===1?'Punkt':'Punkte'}</label>`).join('')}</div><small class="comparison">${auto?`Automatisch verglichen: ${fmt(suggest[i])} ${suggest[i]===1?'Punkt':'Punkte'}. Bei einer gleichwertigen Schreibweise könnt ihr korrigieren.`:m.type==='argument'?'Ihr bewertet nach Textbeleg und Begründung.':`Wortvergleich: ${suggest[i]===c.points?'passende Begriffe gefunden.':'Bitte mit der Musterlösung abgleichen.'} Entscheidend ist der vollständige Inhalt.`}</small></fieldset>`;}).join('')}</div><p class="source-note"><strong>Textnachweis:</strong> Auguste Lechner, <em>Die Abenteuer des Odysseus</em>, ${escape(m.source)}. Die Zahlen beziehen sich auf die bereitgestellte PDF-Ausgabe.</p>${readBack(m,a)}<div id="form-feedback"></div><div class="action-bar"><span class="save-note" id="checked-count">${done} / ${m.criteria.length} Kriterien geprüft</span><div class="action-right"><button class="button dark" data-action="confirm">Punkte sichern ${state.index===11?'& heimkehren':'& weiter'} →</button></div></div>`;}
function game(){const m=MISSIONS[state.index],a=state.answers[state.index],review=state.phase==='review',level=Math.floor(state.index/3);return `${header()}${gameStatus()}<main id="main" class="game-layout page-enter">${route()}<section class="mission" aria-labelledby="mission-title"><div class="mission-banner"><p class="eyebrow">Level ${level+1} · ${LEVELS[level].name}</p><div class="mission-meta"><span>${fmt(m.criteria.reduce((s,c)=>s+c.points,0))} Punkte</span><span class="timer"><span id="timer-label">${timeLabel()}</span><button data-action="timer" aria-label="Zeitmessung ${timerRunning?'pausieren':'fortsetzen'}">${timerRunning?'Ⅱ':'▶'}</button></span></div></div><div class="mission-visual"><img src="./assets/${m.image}.webp" alt="${escape(m.alt)}"><div class="image-text"><p class="eyebrow">Mission ${String(state.index+1).padStart(2,'0')} / 12 · ${escape(m.tag)}</p><h2 id="mission-title" tabindex="-1">${escape(m.title)}</h2></div></div><p class="joke"><span aria-hidden="true">“</span>${escape(m.joke)}</p>${review?reviewScreen(m,a):answerScreen(m,a)}<p class="mission-caption">Freie Illustration · Bilddetails sind keine Textbelege. Richtzeit: ${fmt(m.minutes)} Min.; kein Zeitlimit und kein Tempo-Bonus.${state.mode==='crew'?' Nach dieser Mission die schreibende Person wechseln.':''}</p></section></main>${footer()}`;}
function result(){return `${header()}<main id="main" class="page-enter"><section class="result-hero"><img src="./assets/ithaka-council.webp" alt=""><div class="result-content"><p class="eyebrow">12 von 12 Missionen · Ithaka erreicht</p><h1>Ihr seid <em>angekommen.</em></h1><p class="result-score">${fmt(score(state))}<small> / 60</small></p><p class="result-rank">${rank(score(state))}</p><p class="result-crew">${escape(state.name)} · ${state.mode==='solo'?'Solo-Reise':'Gemeinsam durch den Seegang'}</p></div></section><section class="result-main"><div class="result-actions"><button class="button dark" data-action="export">↓ Ergebnisbericht</button><button class="button outline" data-action="print">Ergebnis drucken</button><button class="button outline" data-action="new">Noch eine Reise?</button></div><div class="result-levels">${LEVELS.map((l,i)=>{const answers=state.answers.slice(i*3,i*3+3),points=answers.reduce((s,a)=>s+a.scores.reduce((x,y)=>x+y,0),0);return `<div class="result-level"><span class="eyebrow">Level ${i+1}</span><h3>${l.name}</h3><p>${fmt(points)} <small>/ ${[9,12,15,24][i]}</small></p></div>`;}).join('')}</div><aside class="learning-note"><strong>Der letzte Schatz: eine bessere Antwort</strong>Öffnet unten eine Mission, bei der noch Punkte fehlen. Erklärt euch gegenseitig, was ihr inzwischen genauer beantworten könnt. Das Ergebnis stammt aus eurem Selbstcheck mit Musterlösungen.</aside><div class="result-details"><h2>Eure Reise im Logbuch</h2>${MISSIONS.map((m,i)=>`<details class="result-row"><summary><span class="result-num">${String(i+1).padStart(2,'0')}</span><span class="result-name">${escape(m.title)}</span><span>${fmt(state.answers[i].scores.reduce((s,v)=>s+v,0))} / ${fmt(m.criteria.reduce((s,c)=>s+c.points,0))}</span></summary>${readBack(m,state.answers[i])}<div class="source-note">${m.criteria.map((c,j)=>`<p><strong>${escape(c.label)} · ${fmt(state.answers[i].scores[j])}/${fmt(c.points)}</strong><br>${escape(c.explanation)}</p>`).join('')}<br>Lechner, ${escape(m.source)}</div></details>`).join('')}</div><div class="certificate"><p>Keine Minuspunkte. Keine Kreuzchenlotterie.<br>Ein langer Heimweg und hoffentlich ein paar klügere Entscheidungen.</p></div></section></main>${footer()}`;}
function render(focus=false){app.innerHTML=view==='welcome'?welcome():state.phase==='result'?result():game();bind();if(focus){window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>document.querySelector('#mission-title')?.focus({preventScroll:true}));}lastTick=Date.now();}
function storeForm(){if(!state||state.phase!=='answer')return;const form=document.querySelector('#mission-form');if(!form)return;for(const f of MISSIONS[state.index].fields??MISSIONS[state.index].events)state.answers[state.index].fields[f.id]=form.elements.namedItem(f.id)?.value??'';save();}
function error(s){const e=document.querySelector('#form-feedback');if(e)e.innerHTML=`<p class="form-error" role="alert">${escape(s)}</p>`;announce(s);}
function move(from,to,focusDirection=null){const a=state.answers[state.index];if(to<0||to>=a.order.length)return;const [moved]=a.order.splice(from,1);a.order.splice(to,0,moved);save();document.querySelector('#order-list').outerHTML=new DOMParser().parseFromString(orderList(a),'text/html').querySelector('#order-list').outerHTML;bindOrder();if(focusDirection)document.querySelector(`[data-index="${to}"][data-direction="${focusDirection}"]`)?.focus();announce(`${moved} steht jetzt an Position ${to+1}.`);}
function bindOrder(){document.querySelectorAll('[data-action="move"]').forEach(b=>b.onclick=()=>move(Number(b.dataset.index),Number(b.dataset.index)+Number(b.dataset.direction),b.dataset.direction));let dragged=null;document.querySelectorAll('.order-item').forEach(li=>{li.addEventListener('dragstart',e=>{dragged=Number(li.dataset.orderIndex);li.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragged));});li.addEventListener('dragover',e=>e.preventDefault());li.addEventListener('dragend',()=>li.classList.remove('dragging'));li.addEventListener('drop',e=>{e.preventDefault();if(dragged!==null)move(dragged,Number(li.dataset.orderIndex));dragged=null;});});}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function startNew(){if(state){openDialog('Eine neue Reise beginnen?',`<p>Der gespeicherte Spielstand von <strong>${escape(state.name)}</strong> wird ersetzt. Lade bei Bedarf zuerst deinen Ergebnisbericht herunter.</p><button class="button outline" id="restart-export">Bericht sichern</button> <button class="button dark" id="restart-confirm">Neues Spiel starten</button>`);document.querySelector('#restart-export').onclick=()=>download('odysseus-ergebnis.txt',report(state),'text/plain;charset=utf-8');document.querySelector('#restart-confirm').onclick=()=>{state=null;try{localStorage.removeItem(STORAGE);}catch{}dialog.close();view='welcome';render(true);};}else{view='welcome';render(true);}}
function act(action){if(action==='home'){storeForm();view='welcome';render(true);}if(action==='resume'){view='game';render(true);}if(action==='new')startNew();if(action==='sound'){state.sound=!state.sound;save();if(state.sound)sound();render();}if(action==='timer'){timerRunning=!timerRunning;const button=document.querySelector('[data-action="timer"]');button.textContent=timerRunning?'Ⅱ':'▶';button.setAttribute('aria-label',`Zeitmessung ${timerRunning?'pausieren':'fortsetzen'}`);lastTick=Date.now();}if(action==='help')openDialog('So kommt ihr nach Ithaka',`<ol><li>Spielt allein oder als Crew von 2–4 Personen an einem Gerät. Es gibt zwölf Missionen in vier Leveln.</li><li>Gebt eure Antworten ein. Bei der Reisereihenfolge nutzt ihr Pfeile oder Ziehen. Abgeben zeigt die Lösungen.</li><li>Klare Namen werden automatisch verglichen. Längere Antworten und Urteile bewertet ihr mit dem eingeblendeten Raster. Inhalt zählt mehr als Wortlaut.</li><li>Eine Rettungsleine pro Reise gibt euch einen Hinweis ohne Punktabzug.</li><li>Die Uhr zählt nur mit. Ihr könnt sie pausieren. Es gibt keine Zeitstrafe.</li><li>Im Crewmodus wechselt nach jeder Mission die schreibende Person. Lehrpersonen können moderieren und den Selbstcheck mitbesprechen.</li></ol><p><strong>Voraussetzung:</strong> Lechners Nacherzählung kennen. Für den Kapitänsrat darf das Buch helfen. Eine Crew spielt zusammen; es gibt keinen geräteübergreifenden Mehrspielermodus.</p>`);
 if(action==='sources')openDialog('Textgrundlage & Illustrationen',`<p><strong>Text:</strong> Auguste Lechner, <em>Die Abenteuer des Odysseus</em>. E-Book-Ausgabe 2020, Tyrolia; neu überarbeitet von Friedrich Stephan. Die Textnachweise in jeder Auflösung beziehen sich auf die PDF-Zählung der bereitgestellten 250-seitigen Datei.</p><p>Das Buch wird hier nicht vervielfältigt. Fragen, Musterlösungen und Scherze wurden für dieses Quiz formuliert. Die modernen Zuspitzungen sind keine Buchzitate.</p><p><strong>Bilder:</strong> Wiederverwendete Illustrationen aus der vorhandenen Unterrichtseinheit «Odysseus-Scherbengericht». Freie künstlerische Darstellungen; Bilddetails sind keine Textbelege. Manche Bilder dienen als Atmosphäre und zeigen nicht die konkrete Episode.</p><p><strong>Bewertung:</strong> Bei Deutungsfragen gibt es keine einzig richtige Meinung. Belege, korrekte Fakten und eine nachvollziehbare Abwägung zählen.</p>`);
 if(action==='privacy')openDialog('Euer Spielstand bleibt auf diesem Gerät',`<p>Antworten, Schiffsname und Punkte werden im lokalen Speicher dieses Browsers abgelegt. Das Spiel versendet diese Angaben nicht an einen Server. Es nutzt keine Analyse-, Werbe- oder KI-Dienste und lädt keine externen Schriftarten.</p><p>Auf gemeinsam benutzten Schulgeräten kann die nächste Person den Spielstand sehen. Mit «Neu anfangen» lässt er sich löschen. Im privaten Browsermodus oder nach dem Löschen der Browserdaten kann er verloren gehen.</p><p>Der Hostinganbieter verarbeitet beim Aufruf die üblichen Verbindungsdaten. Ein heruntergeladener Ergebnisbericht bleibt eine Datei auf eurem Gerät.</p>`);
 if(action==='logbook')openDialog('Euer Logbuch',`<p><strong>${escape(state.name)}</strong> · ${fmt(score(state))} / 60 Punkte</p>${MISSIONS.map((m,i)=>`<div class="log-item"><strong>${String(i+1).padStart(2,'0')} · ${escape(m.title)}</strong>${state.answers[i].confirmed?`${fmt(state.answers[i].scores.reduce((s,v)=>s+v,0))} / ${fmt(m.criteria.reduce((s,c)=>s+c.points,0))} Punkte · abgeschlossen`:i===state.index?'Hier seid ihr gerade.':'Noch vor euch.'}</div>`).join('')}<button class="button outline" id="log-export">Zwischenstand als Bericht</button>`);
 if(action==='logbook')document.querySelector('#log-export').onclick=()=>download('odysseus-zwischenstand.txt',report(state),'text/plain;charset=utf-8');
 if(action==='hint'){const a=state.answers[state.index];if(a.hint){toast(MISSIONS[state.index].hint);return;}if(state.hintUsed)return;storeForm();state.hintUsed=true;a.hint=true;save();render();announce(MISSIONS[state.index].hint);}
 if(action==='export')download('odysseus-ergebnis.txt',report(state),'text/plain;charset=utf-8');
 if(action==='print'){document.querySelectorAll('.result-row,.read-back').forEach(d=>d.open=true);window.print();}
 if(action==='confirm'){const a=state.answers[state.index],m=MISSIONS[state.index];if(!a.reviewed?.every(Boolean)){error('Prüft zuerst jedes Kriterium und wählt dafür die erreichten Punkte.');document.querySelectorAll('.criterion')[a.reviewed?.findIndex(x=>!x)??0]?.scrollIntoView({behavior:'smooth',block:'center'});return;}a.confirmed=true;if(state.index===11){state.phase='result';state.completedAt=new Date().toISOString();save();render(true);sound(true);confetti();}else{state.index++;state.phase='answer';save();render(true);sound(true);if(state.index%3===0)confetti();}announce(`${fmt(score(state))} Punkte gesichert. ${state.phase==='result'?'Ithaka erreicht!':`Mission ${state.index+1} beginnt.`}`);}
}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>{if(b.dataset.action!=='move')b.addEventListener('click',()=>act(b.dataset.action));});document.querySelector('#start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;state=freshState(form.elements.name.value,form.elements.mode.value);view='game';save();render(true);});document.querySelector('#mission-form')?.addEventListener('input',storeForm);document.querySelector('#mission-form')?.addEventListener('submit',e=>{e.preventDefault();storeForm();const m=MISSIONS[state.index],a=state.answers[state.index],empty=(m.fields??m.events).find(f=>!a.fields[f.id]?.trim());if(empty){error('Füllt bitte jedes Antwortfeld aus. Eine Vermutung ist besser als ein leeres Feld.');document.querySelector(`#answer-${empty.id}`)?.focus();return;}a.submitted=true;const suggested=suggestions(m,a);a.scores=m.criteria.map((c,i)=>autoCriterion(m,c,i)?suggested[i]:0);a.reviewed=m.criteria.map((c,i)=>autoCriterion(m,c,i));state.phase='review';save();render(true);announce('Antworten abgegeben. Vergleicht jetzt mit den Lösungen.');});document.querySelectorAll('[data-score-index]').forEach(el=>el.addEventListener('change',()=>{const a=state.answers[state.index],index=Number(el.dataset.scoreIndex);a.scores[index]=Number(el.value);a.reviewed[index]=true;save();document.querySelector('#review-total').textContent=`${fmt(a.scores.reduce((s,v)=>s+v,0))} / ${fmt(MISSIONS[state.index].criteria.reduce((s,c)=>s+c.points,0))} Punkte`;document.querySelector('#checked-count').textContent=`${a.reviewed.filter(Boolean).length} / ${a.reviewed.length} Kriterien geprüft`;document.querySelector('#form-feedback').innerHTML='';}));bindOrder();}
setInterval(()=>{const now=Date.now();if(state&&view==='game'&&state.phase==='answer'&&timerRunning&&!document.hidden&&!dialog.open){state.answers[state.index].elapsed+=Math.min((now-lastTick)/1000,2);const t=document.querySelector('#timer-label');if(t)t.textContent=timeLabel();save();}lastTick=now;},1000);
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();save();});window.addEventListener('pagehide',()=>{storeForm();save();});
render();
